update public.news_updates set summary='On 23 July 2026, the European Council adopted its 21st package of Russia sanctions as well as additional measures targeting Belarus.', full_summary='On 23 July 2026, the European Council adopted its 21st package of Russia sanctions as well as additional measures targeting Belarus. The package concentrates on sectors with the greatest impact on Russia’s war economy, including energy, shipping, gold, financial services (including crypto), trade, and the Russian military-industrial complex.', source_url='https://sanctionsnews.bakermckenzie.com/eu-adopts-21st-russia-sanctions-package/', updated_at=now() where id='8a16d314-19d5-4ba7-b82e-6e15fa319504';
update public.news_updates set summary='The EU sanctioned Russian GRU officers, hacktivist groups and bulletproof hosting providers for cyberattacks against European critical infrastructure, adding asset freezes and travel bans under its cyber sanctions regime.', full_summary='The EU sanctioned Russian GRU officers, hacktivist groups and bulletproof hosting providers for cyberattacks against European critical infrastructure, adding asset freezes and travel bans under its cyber sanctions regime.', source_url='https://industrialcyber.co/critical-infrastructure/eu-sanctions-russian-gru-officers-hacktivists-and-hosting-firms-over-cyberattacks-on-critical-infrastructure/', updated_at=now() where id='13c8248c-0533-4089-978d-7186b16452c9';
update public.news_updates set summary='The Central Bank of the UAE''s new Remuneration Regulation for Banks and Insurance Companies (Circular No. 5/2026) marks a significant development in the UAE''s prudential regulatory framework.', full_summary='The Central Bank of the UAE''s new Remuneration Regulation for Banks and Insurance Companies (Circular No. 5/2026) marks a significant development in the UAE''s prudential regulatory framework, bringing bankers'' pay under closer supervisory scrutiny.', source_url='https://www.dentons.com/en/insights/alerts/2026/july/29/financial-fair-pay-uae-central-bank-brings-bankers-pay-under-the-regulatory-compliance-spotlight', updated_at=now() where id='d7671c12-5ed4-49bd-8ab5-577e8dfd2fcb';
update public.news_updates set summary='In anticipation of the Financial Action Task Force’s fifth round of mutual evaluations, the UAE has overhauled its anti-money laundering, counter-terrorist financing and counter-proliferation financing framework.', full_summary='In anticipation of the Financial Action Task Force’s fifth round of mutual evaluations, which is currently underway, the UAE has overhauled its anti-money laundering, counter-terrorist financing and counter-proliferation financing framework, introducing new supervisory expectations for regulated firms.', source_url='https://www.freshfields.com/en/our-thinking/blogs/risk-and-compliance/keeping-pace-with-the-uaes-evolving-anti-money-laundering-counter-terrorism-fin-102ndhv', updated_at=now() where id='8f5818b9-3d3f-4409-be71-32e50d169425';
update public.news_updates set summary='Azentio Software has launched a pre-approved UAE e-invoicing solution integrated within Azentio ERP to help businesses comply with the Federal Tax Authority’s e-invoicing mandate starting January 2027.', full_summary='Azentio Software has launched a pre-approved UAE e-invoicing solution integrated within Azentio ERP to help businesses comply with the Federal Tax Authority’s upcoming e-invoicing mandate starting January 2027, featuring AI capabilities for enhanced data accuracy and streamlined tax compliance, after receiving pre-approved ASP status from the UAE Ministry of Finance.', source_url='https://erp.today/azentio-uae-e-invoicing-erp-tax-compliance/', updated_at=now() where id='0a7c93cd-97c5-46f3-b4e3-c47a89db11b6';
update public.news_updates set summary='Fragomen examines cross-functional compliance in the UAE, outlining how immigration and employment obligations intersect and the risks employers face when sponsorship, labour and regulatory requirements are managed in isolation.', full_summary='Fragomen examines cross-functional compliance in the UAE, outlining how immigration and employment obligations intersect and the risks employers face when sponsorship, labour and regulatory requirements are managed in isolation.', source_url='https://www.fragomen.com/insights/cross-functional-compliance-in-the-uae-navigating-immigration-and-employment-risks.html', title='Cross-Functional Compliance in the UAE: Navigating Immigration and Employment Risks', updated_at=now() where id='457190c3-5b7f-471c-8da9-c8c81707723b';
update public.news_updates set summary='On 30 June, the United States and members of the Gulf Cooperation Council jointly imposed sanctions on Hezbollah’s financial infrastructure through the Terrorist Financing Targeting Center (TFTC).', full_summary='On 30 June, the United States and members of the Gulf Cooperation Council (GCC) jointly imposed sanctions on Hezbollah’s financial infrastructure through the Terrorist Financing Targeting Center (TFTC). The targets include Al-Qard Al-Hassan (AQAH), a financial branch of Hezbollah, and Bayt al-Mal, described by the US Treasury as the group’s unofficial treasury, as well as senior leaders of both organizations. The United States had previously sanctioned all 31 entities and individuals targeted.', source_url='https://www.fdd.org/analysis/2026/07/01/gulf-states-sanction-hezbollah-but-qatar-has-a-flawed-record-on-terror-finance-enforcement/', updated_at=now() where id='2e990c47-e4b3-444a-ad5e-e6a680d41c3c';
update public.news_updates set summary='The Central Bank of the UAE announced the development of a nationwide unified Know Your Customer (e-KYC) platform, following a technical partnership agreement with Norbloc AB.', full_summary='The Central Bank of the UAE (CBUAE) announced the development of the nationwide unified Know Your Customer (e-KYC) platform, following the signing of a technical partnership agreement with the global technology company Norbloc AB.', source_url='https://ffnews.com/newsarticle/fintech/cbuae-develops-e-kyc-platform-and-appoints-norbloc-ab-as-a-technology-partner', updated_at=now() where id='b3d333e5-2990-4c6d-b4f2-72679f63fffe';
update public.news_updates set summary='Azentio Software, a provider of BFSI and ERP software in emerging markets, has announced the launch of its UAE e-invoicing solution with pre-approved ASP status and AI-powered ERP capabilities.', full_summary='Azentio Software, a provider of BFSI and ERP software in emerging markets, has announced the launch of its UAE e-invoicing solution with pre-approved ASP status and AI-powered ERP capabilities.', source_url='https://www.prnewswire.co.uk/news-releases/azentio-launches-uae-e-invoicing-solution-with-pre-approved-asp-status-and-ai-powered-erp-capabilities-302820522.html', updated_at=now() where id='36d55e7c-6ae9-4d64-864a-f2c0488cd25e';
update public.news_updates set summary='Taptap Send has secured three licences from the UAE Central Bank, marking a major expansion of its financial services offering in the UAE.', full_summary='Taptap Send has secured three licences from the UAE Central Bank, marking a major expansion of its financial services and digital payments offering in the UAE.', source_url='https://techafricanews.com/2026/07/08/taptap-send-secures-three-uae-central-bank-licenses-to-expand-digital-payments/', updated_at=now() where id='7002e780-f4a1-4fe8-9cce-fd2785789a85';
